\section{উদাহরণ-৬.৯: একটি উত্তল লেন্সের ফোকাস দূরত্ব 0.2 m। পানিতে এর ফোকাস দূরত্ব কত? (কাচ ও পানির পরম প্রতিসরণাঙ্ক যথাক্রমে $\frac{3}{2}$ এবং $\frac{4}{3}$)}

ধরা যাক, লেন্সটির পৃষ্ঠদ্বয়ের ব্যাসার্ধ যথাক্রমে $r_{1}$ ও $r_{2}$. বায়ুতে ফোকাস দূরত্ব $f_{1}$ ও বায়ুর সাপেক্ষে কাচের প্রতিসরণাঙ্ক $\mu_{g}$ হলে আমরা পাই,

\begin{equation}
\frac{1}{f_{1}} = (\mu_{g} - 1) \left( \frac{1}{r_{1}} - \frac{1}{r_{2}} \right)
\tag{a}
\end{equation}

পানিতে ফোকাস দূরত্ব $f_{2}$ ও পানির সাপেক্ষে কাচের প্রতিসরণাঙ্ক $\mu_{g}$ হলে আমরা পাই,

\begin{equation}
\frac{1}{f_{2}} = (\mu_{g} - 1) \left( \frac{1}{r_{1}} - \frac{1}{r_{2}} \right)
\tag{b}
\end{equation}

সমীকরণ (a) কে (b) দ্বারা ভাগ করে,

\begin{equation}
\frac{f_{2}}{f_{1}} = \frac{\mu_{g} - 1}{\mu_{g} - 1} = \frac{\frac{3}{2} - 1}{\frac{9}{8} - 1} = \frac{\frac{1}{2}}{\frac{1}{8}} = \frac{1}{2} \times 8 = 4 \quad \text{[যেহেতু, $\mu_{g} = \frac{3}{2} \times \frac{3}{4} = \frac{9}{8}$]}
\end{equation}

\begin{equation}
\therefore f_{2} = 4 \times f_{1} = 4 \times 0.2 \, \text{m} = 0.8 \, \text{m}
\end{equation}

