\textbf{আমরা জানি, বিবর্ধন-}

\begin{equation}
m = -\frac{v}{u} = \frac{l'}{l}
\end{equation}

\begin{equation}
\therefore l' = -\frac{vl}{u} = -\frac{(-48 \text{ cm})(6 \text{ cm})}{12 \text{ cm}} = 24 \text{ cm}
\end{equation}

\textbf{এক্ষেত্রে বিষ্ম বাস্তব অবস্থাব দু-ই হতে পারে। বাস্তব বিষ্মের ক্ষেত্রে বিবর্ধন খানাত্তক। সুতরাং,}

\begin{equation}
-3 = -\frac{v}{u}
\end{equation}

\begin{equation}
\therefore v = 3u
\end{equation}

\textbf{লেন্সের সাধারণ সমীকরণ থেকে আমরা পাই,}

\begin{equation}
\frac{1}{u} + \frac{1}{v} = \frac{1}{f}
\end{equation}

\textbf{বা, $\frac{1}{u} + \frac{1}{3u} = \frac{1}{0.75 \text{ m}}$}

\textbf{বা, $\frac{4}{3u} = \frac{1}{0.75 \text{ m}}$}

\begin{equation}
\therefore u = 1 \text{ m}
\end{equation}

\textbf{আবার অবস্থাব বিষ্মের ক্ষেত্রে বিবর্ধন ধনাত্তক। সুতরাং,}

\begin{equation}
3 = -\frac{v}{u}
\end{equation}

\begin{equation}
\therefore v = -3u
\end{equation}

\textbf{লেন্সের সমীকরণ থেকে আমরা পাই,}

\begin{equation}
\frac{1}{u} + \frac{1}{v} = \frac{1}{f}
\end{equation}

