\section{পদার্থবিজ্ঞান দ্বিতীয় পত্র}

\subsection{উদাহরণ-৬.২৩:}

একটি দূরবিক্ষন যন্ত্রে ব্যবহৃত উত্তল লেন্সগুলির ফোকাস দূরত্ব যথাক্রমে 10 cm এবং 1 cm। অভিলক্ষ্য হতে 1 m দূরে অবস্থিত একটি বস্তুর ওপর যন্ত্রটি ফোকাস করা হলে চক্ষু হতে 25 cm দূরে চূড়ান্ত প্রতিবিম্ব দেখা যায়। প্রতিবিষ্টি কতগুলো বিবর্ধিত হয়েছিল নির্ণয় করো।

অভিলক্ষ্যের ক্ষেত্রে আমরা পাই,

\begin{equation}
\frac{1}{u_{o}} + \frac{1}{v_{o}} = \frac{1}{f_{o}}
\end{equation}

বা, $\frac{1}{v_{o}} = \frac{1}{10 \text{ cm}} - \frac{1}{100 \text{ cm}} = \frac{9}{100 \text{ cm}}$

\begin{equation}
\therefore v_{o} = \frac{100 \text{ cm}}{9}
\end{equation}

আবার, অভিনেত্রের ক্ষেত্রে আমরা পাই,

\begin{equation}
\frac{1}{u_{e}} + \frac{1}{v_{e}} = \frac{1}{f_{e}}
\end{equation}

বা, $\frac{1}{u_{e}} = \frac{1}{1 \text{ cm}} - \frac{1}{-25 \text{ cm}} = \frac{25 + 1}{25 \text{ cm}}$

\begin{equation}
\therefore u_{e} = \frac{25 \text{ cm}}{26}
\end{equation}

সূত্রাং, মোট বিবর্ধন, $m = m_{o} \times m_{e} = \frac{v_{o}}{u_{o}} \times \frac{v_{e}}{u_{e}} = \frac{100 \text{ cm}}{9 \times 100 \text{ cm}} \times \frac{25 \text{ cm} \times 26}{25 \text{ cm}} = 2.89$

\subsection{উদাহরণ-৬.২৪:}

একটি দূরবিক্ষনের উত্তল লেন্স দুইটির ফোকাস দূরত্ব যথাক্রমে 30 cm এবং 3 cm। এদের মধ্যকার দূরত্ব 33 cm। যন্ত্রকে চাঁদের দিকে ফোকাস করা হলে চাঁদ অভিলক্ষ্য 30° কোণ উৎপন্ন করে। এই যন্ত্র দ্বারা সূর্য চাঁদের প্রতিবিম্ব দর্শনের চোখে কত কোণ উৎপন্ন করবে?

আমরা জানি, অসীমে ফোকাসের ক্ষেত্রে দূরবিক্ষন বিবর্ধন-

\begin{equation}
m = \frac{f_{o}}{f_{e}} = \frac{30 \text{ cm}}{3 \text{ cm}} = 10 = \frac{\text{প্রতিবিষ্টি কর্তৃক সূর্য কোণ}}{\text{বস্তু কর্তৃক সূর্য কোণ}}
\end{equation}

এখানে,

\begin{equation}
\text{অভিলক্ষ্যের ফোকাস দূরত্ব} \ f_{o} = 30 \text{ cm}
\end{equation}

\end{document}

