\subsection{উদাহরণ-৬. জেমিমা বায়ুতে একটি ফাঁচের উত্তল লেন্স নিয়ে কাজ করছিল যার তলমন্ডির ব্যাসার্ধ যথাক্রমে 15 cm এবং 30 cm | এবং $\mu_{\text{g}} = \frac{3}{2}$ এবং $\mu_{\text{w}} = \frac{4}{3}$. | তা. সে ২০১৬।

ক. লেন্সটির ফোকাস দূরত্ব নির্ণয় করো।

খ. লেন্সটিকে পানিতে নিমজ্জিত করলে এর ক্ষমতার কোনো পরিবর্তন হবে কি না — বিশ্লেষণশীল মতামত দাও।

ক. আমরা জানি,

\begin{equation}
\frac{1}{f_{\text{a}}} = (\mu_{\text{g}} - 1) \left( \frac{1}{r_{1}} - \frac{1}{r_{2}} \right)
\end{equation}

\begin{equation}
= \left( \frac{3}{2} - 1 \right) \left( \frac{1}{+15 \text{ cm}} - \frac{1}{-30 \text{ cm}} \right)
\end{equation}

\begin{equation}
= \frac{1}{2} \left( \frac{3}{30 \text{ cm}} \right) = \frac{1}{20 \text{ cm}}
\end{equation}

\begin{equation}
\therefore f_{\text{a}} = 20 \text{ cm}
\end{equation}

খ. পানিতে লেন্সটির ফোকাস দূরত্ব $f_{\text{w}}$ হলে,

\begin{equation}
\frac{1}{f_{\text{w}}} = (\mu_{\text{g}} - 1) \left( \frac{1}{r_{1}} - \frac{1}{r_{2}} \right) = \left( \frac{3}{2} - 1 \right) \left( \frac{1}{15 \text{ cm}} - \frac{1}{-30 \text{ cm}} \right) = \frac{1}{8} \left( \frac{3}{30 \text{ cm}} \right) = \frac{1}{80 \text{ cm}}
\end{equation}

\begin{equation}
\therefore f_{\text{w}} = 80 \text{ cm} = 0.80 \text{ m}
\end{equation}

\begin{equation}
\therefore \text{পানিতে লেন্সের ক্ষমতা, } P_{\text{w}} = \frac{1}{f_{\text{w}}} = \frac{1}{0.80 \text{ m}} = +1.25 \text{ D}
\end{equation}

বায়ুতে লেন্সের ক্ষমতা, $P_{\text{a}} = \frac{1}{f_{\text{a}}} = \frac{1}{0.2 \text{ m}} = +5 \text{ D}$

গাণিতিক বিশ্লেষণ থেকে দেখা যায়, লেন্সটিকে পানিতে নিমজ্জিত করলে এর ক্ষমতা হার পাবে।

\subsection{উদাহরণ-৭. একজন ছাত্র 100 cm ফোকাস দূরত্বের একটি লেন্স নিয়ে 0.01 cm দৈর্ঘ্যের কণা পরীক্ষা করছিল। পরে সে একটি নলের এক প্রান্তে এই লেন্স ও অন্য প্রান্তে 4 cm ফোকাস দূরত্বের অন্য লেন্স লাগিয়ে আকাশ পর্যবেক্ষণ করল। | তা. সে ১৯।

ক. ছেটি কণাগুলোকে কত বড় দেখেছিল?

খ. নল ব্যবহার করার পর আকাশের কোনো বস্তুকে দেখতে চাইলে কোন ফোকাসিং এ বেশি বড় দেখাবে গাণিতিকভাবে যাচাই করে।

ক. স্পষ্ট দর্শনের নিকটম দূরত্বে নেই হলে বিবর্ধন,

\begin{equation}
M = 1 + \frac{D}{f}
\end{equation}

\begin{equation}
\text{বা, } \frac{l'}{l} = 1 + \frac{25}{100} = 1.25
\end{equation}

\begin{equation}
\therefore l' = 1.25 \times 0.01 \text{ cm} = 0.0125 \text{ cm}
\end{equation}

খ. উদ্দীপকের লেন্সযুক্ত একটি নলের দুই প্রান্তে রেখে আকাশ দেখার জন্য যে যন্ত্র তৈরি করা হয়েছে তা হল দূরবীক্ষণ যন্ত্র।

\begin{equation}
\text{সুতরাং অভিনেত্রীর ফোকাস দূরত্ব, } f_{\text{o}} = 100 \text{ cm}
\end{equation}

\begin{equation}
\text{অভিনেত্রীর ফোকাস দূরত্ব, } f_{\text{e}} = 4 \text{ cm}
\end{equation}

এখন, আকাশের কোনো বস্তু দেখার জন্য অসীম দূরত্ব বা স্বাভাবিক ফোকাসিংয়ের ক্ষেত্রে বিবর্ধন—

\begin{equation}
M_{1} = \frac{f_{\text{o}}}{f_{\text{e}}} = \frac{100}{4} = 25
\end{equation}

আবার, স্পষ্ট দর্শনের নিকটম দূরত্বে ফোকাসিং এর ক্ষেত্রে বিবর্ধন—

\begin{equation}
M_{2} = \frac{f_{\text{o}}}{f_{\text{e}}} \left( 1 + \frac{f_{\text{e}}}{D} \right) = \frac{100}{4} \left( 1 + \frac{4}{25} \right) \quad (\because \text{নিকট বিন্দুর দূরত্ব, } D = 25 \text{ cm})
\end{equation}

\begin{equation}
= 29
\end{equation}

